export function history(stock){let seed=stock.seed;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};let value=stock.price*.85;const values=[];const end=new Date('2026-11-06T12:00:00Z');const dates=[];for(let d=new Date(end);dates.length<90;d.setUTCDate(d.getUTCDate()-1))if(d.getUTCDay()!==0&&d.getUTCDay()!==6)dates.unshift(new Date(d));for(let i=0;i<90;i++){value*=1+stock.drift+(rand()-.48)*stock.vol+Math.sin(i*.55)*.002;values.push(value);}const factor=stock.price/values.at(-1);return values.map((v,i)=>({date:dates[i].toISOString().slice(0,10),close:Math.round(v*factor*100)/100,volume:Math.round((18+rand()*36)*1e6)}));}
export function predictNext(closes){const window=closes.slice(-6);if(window.length<6)throw new Error('Six closing prices are required');const slope=(window.at(-1)-window[0])/5;return Math.max(.01,window.at(-1)+slope*.55);}
export function metrics(rows){const closes=rows.map(r=>r.close),errors=[];let correct=0,nonflat=0,totalPct=0;for(let i=closes.length-30;i<closes.length;i++){const forecast=predictNext(closes.slice(0,i)),error=forecast-closes[i];errors.push(error);totalPct+=Math.abs(error)/closes[i]*100;const observed=Math.sign(closes[i]-closes[i-1]);if(observed!==0){nonflat++;if(Math.sign(forecast-closes[i-1])===observed)correct++;}}return{mae:errors.reduce((a,e)=>a+Math.abs(e),0)/errors.length,mape:totalPct/errors.length,direction:nonflat?correct/nonflat*100:0,correct,total:nonflat,rmse:Math.sqrt(errors.reduce((a,e)=>a+e*e,0)/errors.length),errors};}
export function forecast(rows){const closes=rows.map(r=>r.close),last=closes.at(-1),step=predictNext(closes)-last,rmse=metrics(rows).rmse;let date=new Date(rows.at(-1).date+'T12:00:00Z');return Array.from({length:5},(_,i)=>{do{date.setUTCDate(date.getUTCDate()+1);}while([0,6].includes(date.getUTCDay()));const median=Math.max(.01,last+step*(i+1)),width=1.645*rmse*Math.sqrt(i+1);return{date:date.toISOString().slice(0,10),median,low:Math.max(.01,median-width),high:median+width};});}
export function orderQuote(amountCents,priceCents){if(!Number.isSafeInteger(amountCents)||amountCents<=0||!Number.isInteger(priceCents)||priceCents<1||priceCents>99)throw new Error('Enter a valid order amount');const shares=Math.floor(amountCents/priceCents);return{shares,costCents:shares*priceCents,payoutCents:shares*100};}
export function placeOrder(portfolio,market,side,amountCents){if(!['yes','no'].includes(side))throw new Error('Choose Yes or No');const price=side==='yes'?market.yes:100-market.yes,q=orderQuote(amountCents,price);if(q.shares<1)throw new Error('Increase the amount to buy at least one share.');if(q.costCents>portfolio.cashCents)throw new Error('Your paper balance is too low for this order.');return{cashCents:portfolio.cashCents-q.costCents,trades:[{id:globalThis.crypto.randomUUID(),marketId:market.id,side,priceCents:price,shares:q.shares,costCents:q.costCents,time:new Date().toISOString()},...portfolio.trades]};}
export function maximumPayoutCents(trades){const events=new Map();for(const trade of trades){const totals=events.get(trade.marketId)||{yes:0,no:0};totals[trade.side]+=trade.shares;events.set(trade.marketId,totals);}return [...events.values()].reduce((sum,t)=>sum+Math.max(t.yes,t.no)*100,0);}
